PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

INSERT INTO core_publication
  (publication_type, pmid, authors, title, journal, publication_date, url,
   contains_promoter_data, contains_expression_data, submission_notes, curation_complete,
   reported_TF, reported_species)
SELECT
  'pubmed',
  '39101802',
  'Lacoul A, Kirschen MP',
  'You Say Potato, I Say Potatoe: Seizure Prophylaxis After Pediatric Traumatic Brain Injury.',
  'Pediatric critical care medicine : a journal of the Society of Critical Care Medicine and the World Federation of Pediatric Intensive and Critical Care Societies',
  '2024 Aug 1',
  'https://doi.org/10.1097/PCC.0000000000003543',
  0,
  1,
  'Taxonomy test 2',
  1,
  'TraR',
  'Pseudolactococcus laudensis'
WHERE NOT EXISTS (
  SELECT 1 FROM core_publication WHERE pmid='39101802'
);

UPDATE core_publication
SET
  authors = CASE WHEN authors IS NULL OR authors='' THEN 'Lacoul A, Kirschen MP' ELSE authors END,
  title = CASE WHEN title IS NULL OR title='' THEN 'You Say Potato, I Say Potatoe: Seizure Prophylaxis After Pediatric Traumatic Brain Injury.' ELSE title END,
  journal = CASE WHEN journal IS NULL OR journal='' THEN 'Pediatric critical care medicine : a journal of the Society of Critical Care Medicine and the World Federation of Pediatric Intensive and Critical Care Societies' ELSE journal END,
  publication_date = CASE WHEN publication_date IS NULL OR publication_date='' THEN '2024 Aug 1' ELSE publication_date END,
  url = CASE WHEN url IS NULL OR url='' THEN 'https://doi.org/10.1097/PCC.0000000000003543' ELSE url END,
  reported_TF = CASE WHEN reported_TF IS NULL OR reported_TF='' THEN 'TraR' ELSE reported_TF END,
  reported_species = CASE WHEN reported_species IS NULL OR reported_species='' THEN 'Pseudolactococcus laudensis' ELSE reported_species END,
  contains_promoter_data = 0,
  contains_expression_data = 1,
  curation_complete = 1,
  submission_notes = CASE
    WHEN submission_notes IS NULL OR submission_notes='' THEN 'Taxonomy test 2'
    ELSE submission_notes
  END
WHERE pmid='39101802';

INSERT INTO core_tf (name, family_id, description)
SELECT 'TraR', 2, 'Described in Agrobacterium tumefaciens, TraR is a homologue of the Vibrio fischeri LuxR quorum sensing regulator. It is encoded by the the tumour-inducing (Ti) plasmid and it activates the tra genes required for plasmid transfer. TraR is induced by opines and recognizes 18 bp palindromic DNA sequences [PMID::12087407].'
WHERE NOT EXISTS (
  SELECT 1 FROM core_tf WHERE lower(name)=lower('TraR')
);

UPDATE core_tf
SET
  family_id = COALESCE(family_id, 2),
  description = CASE WHEN description IS NULL THEN 'Described in Agrobacterium tumefaciens, TraR is a homologue of the Vibrio fischeri LuxR quorum sensing regulator. It is encoded by the the tumour-inducing (Ti) plasmid and it activates the tra genes required for plasmid transfer. TraR is induced by opines and recognizes 18 bp palindromic DNA sequences [PMID::12087407].' ELSE description END
WHERE lower(name)=lower('TraR');

INSERT INTO core_tfinstance (refseq_accession, uniprot_accession, description, TF_id, notes, GO_term_id)
SELECT
  'WP_486186680.1',
  'A0A7V8MZ06',
  'Undecaprenyl-diphosphatase',
  (SELECT TF_id FROM core_tf WHERE lower(name)=lower('TraR') LIMIT 1),
  '',
  ''
WHERE NOT EXISTS (
  SELECT 1 FROM core_tfinstance WHERE uniprot_accession='A0A7V8MZ06'
);

UPDATE core_tfinstance
SET
  TF_id = COALESCE(TF_id, (SELECT TF_id FROM core_tf WHERE lower(name)=lower('TraR') LIMIT 1)),
  refseq_accession = COALESCE(NULLIF(refseq_accession,''), 'WP_486186680.1'),
  description = COALESCE(NULLIF(description,''), 'Undecaprenyl-diphosphatase'),
  notes = COALESCE(notes, ''),
  GO_term_id = COALESCE(GO_term_id, '')

WHERE uniprot_accession='A0A7V8MZ06';

INSERT INTO core_curation
  (TF_species, site_species, experimental_process, forms_complex,
   complex_notes, notes, last_modified, curator_id, publication_id, created, validated_by_id)
VALUES
  ('Pseudolactococcus laudensis', 'Pseudolactococcus laudensis', NULL,
   0, NULL, 'Taxonomy test 2',
   datetime('now'), (SELECT curator_id FROM core_curator ORDER BY curator_id LIMIT 1), (SELECT publication_id FROM core_publication WHERE pmid='39101802' LIMIT 1), datetime('now'), NULL);

INSERT INTO core_curation_TF_instances (curation_id, tfinstance_id)
SELECT (SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='39101802' LIMIT 1) ORDER BY curation_id DESC LIMIT 1), (SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='A0A7V8MZ06' LIMIT 1)
WHERE NOT EXISTS (
  SELECT 1 FROM core_curation_TF_instances
  WHERE curation_id=(SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='39101802' LIMIT 1) ORDER BY curation_id DESC LIMIT 1) AND tfinstance_id=(SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='A0A7V8MZ06' LIMIT 1)
);

